set-variable.value:
@{
        var candidate = context.Request.Headers.GetValueOrDefault("X-Correlation-ID", "");
        return candidate.Length == 36 && System.Text.RegularExpressions.Regex.IsMatch(candidate, @"\A[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z")
            ? candidate.ToLowerInvariant() : Guid.NewGuid().ToString();
    }
